fn archive(root:&Path,dir:&Path,out:&Path,index:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();if e.file_type().unwrap().is_dir(){archive(root,&p,out,index);continue}if !e.file_type().unwrap().is_file(){continue}let rel=p.strip_prefix(root).unwrap();let path=rel.to_string_lossy();if path.contains("/raw-")||path.contains("/script-")||name=="raw.txt"||name=="samples.txt"{continue}if !["rs","json","md","log","txt","h","c","proof","public"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("")){continue}let dest=out.join(rel);fs::create_dir_all(dest.parent().unwrap()).unwrap();fs::copy(&p,&dest).unwrap();assert_eq!(hash(&p),hash(&dest));index.insert(rel.display().to_string(),hash(dest));}}
